// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";

interface IAcademy {
    function activeStudents(address _student) external view returns (bool);
}

/// @dev No hay fondos acumulados para retirar.
error NoFundsToWithdraw();
/// @dev La dirección de destino del retiro es la dirección cero.
error InvalidDestination();
/// @dev La transferencia de ETH falló.
error TransferFailed();

/**
 * @title CompositionRegistry
 * @author Valentino - UTN Blockchain TPI
 * @notice Permite a los alumnos y externos registrar el hash criptográfico de sus
 * obras musicales en IPFS y la EVM (Proof of Existence) usando el patrón Commit-Reveal para evitar front-running.
 */
contract CompositionRegistry is AccessControl {
    bytes32 public constant FEE_SETTER_ROLE = keccak256("FEE_SETTER_ROLE");

    struct Composition {
        string ipfsHash;     // CID v1 de la obra en IPFS.
        string title;        // Título descriptivo.
        address author;      // Creador intelectual.
        uint32 timestamp;    // Marca temporal del bloque.
    }

    IAcademy public academyContract;
    uint256 public registrationFee;
    uint256 public compositionCount;

    // Autor => (Hash de Compromiso => Altura del Bloque de Registro)
    mapping(address => mapping(bytes32 => uint256)) public commits;

    // ID Registro => Composición
    mapping(uint256 => Composition) public registry;

    event CompositionCommitted(address indexed author, bytes32 indexed commitHash);
    event CompositionRegistered(address indexed author, uint256 indexed compositionId, string ipfsHash);
    event FeeUpdated(uint256 oldFee, uint256 newFee);
    event AcademyContractUpdated(address indexed oldAcademy, address indexed newAcademy);

    /**
     * @notice Inicializa el contrato con la Academia, la tasa de registro y el administrador.
     * @param _academyContract Dirección del contrato ConservatoryAcademy para validar regularidad de alumnos.
     * @param _initialFee Tasa de registro en wei exigida a compositores externos (alumnos exentos).
     * @param _admin Dirección que recibirá DEFAULT_ADMIN_ROLE y FEE_SETTER_ROLE.
     */
    constructor(address _academyContract, uint256 _initialFee, address _admin) {
        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _grantRole(FEE_SETTER_ROLE, _admin);
        academyContract = IAcademy(_academyContract);
        registrationFee = _initialFee;
    }

    /**
     * @notice Actualiza la dirección del contrato de Academia usado para validar regularidad.
     * @param _newAcademy Nueva dirección del contrato ConservatoryAcademy.
     */
    function setAcademyContract(address _newAcademy) external onlyRole(DEFAULT_ADMIN_ROLE) {
        emit AcademyContractUpdated(address(academyContract), _newAcademy);
        academyContract = IAcademy(_newAcademy);
    }

    /**
     * @notice Modifica la tasa de registro cobrada a compositores externos.
     * @param _newFee Nuevo valor de la tasa en wei.
     */
    function setRegistrationFee(uint256 _newFee) external onlyRole(FEE_SETTER_ROLE) {
        emit FeeUpdated(registrationFee, _newFee);
        registrationFee = _newFee;
    }

    /**
     * @notice PASO 1 (Commit): Registra un compromiso temporal secreto.
     * @param _commitHash Calculado como keccak256(abi.encodePacked(ipfsHash, msg.sender, salt)).
     */
    function commitComposition(bytes32 _commitHash) external {
        commits[msg.sender][_commitHash] = block.number;
        emit CompositionCommitted(msg.sender, _commitHash);
    }

    /**
     * @notice PASO 2 (Reveal & Register): Revela la obra y finaliza el registro.
     * @dev Implementa el patrón CEI. Exige al menos 1 bloque de diferencia para evitar inyecciones en el mempool.
     * @param _ipfsHash CID v1 del archivo de la obra almacenado en IPFS.
     * @param _title Título descriptivo de la composición.
     * @param _salt Valor secreto utilizado en la fase de commit para construir el hash de compromiso.
     */
    function registerComposition(
        string memory _ipfsHash,
        string memory _title,
        bytes32 _salt
    ) external payable {
        // --- Checks ---
        bytes32 derivedHash = keccak256(abi.encodePacked(_ipfsHash, msg.sender, _salt));
        uint256 commitBlock = commits[msg.sender][derivedHash];

        require(commitBlock > 0, "No existe un compromiso registrado previo");
        require(block.number > commitBlock, "Revelacion en el mismo bloque bloqueada");

        bool isStudent = academyContract.activeStudents(msg.sender);

        if (!isStudent) {
            require(msg.value >= registrationFee, "Tasa de registro insuficiente para externos");
        } else {
            // Evitar acumular saldo inútil si el alumno mandó dinero de más por error
            require(msg.value == 0, "Alumnos regulares no pagan tasa de registro");
        }

        // --- Effects ---
        compositionCount++;
        registry[compositionCount] = Composition({
            ipfsHash: _ipfsHash,
            title: _title,
            author: msg.sender,
            timestamp: uint32(block.timestamp)
        });

        delete commits[msg.sender][derivedHash];

        // --- Interactions ---
        // (ninguna interacción externa en este flujo; el ETH queda retenido en el contrato)

        emit CompositionRegistered(msg.sender, compositionCount, _ipfsHash);
    }

    /**
     * @notice Permite retirar fondos de forma segura hacia la tesorería institucional.
     * @dev Implementa el patrón CEI: valida condiciones antes de ejecutar la transferencia externa.
     * @param _destination Dirección payable de la tesorería que recibirá el saldo acumulado.
     */
    function withdrawFunds(address payable _destination) external onlyRole(DEFAULT_ADMIN_ROLE) {
        // --- Checks ---
        if (_destination == address(0)) revert InvalidDestination();
        uint256 balance = address(this).balance;
        if (balance == 0) revert NoFundsToWithdraw();

        // --- Effects ---
        // No hay estado interno que refleje el balance (se vacía el contrato completo).

        // --- Interactions ---
        (bool success, ) = _destination.call{value: balance}("");
        if (!success) revert TransferFailed();
    }
}

contracts/ConservatoryAcademy.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";

/**
 * @title ConservatoryAcademy
 * @author TypeIt - UTN Blockchain TPI
 * @notice Gestiona el historial académico de los alumnos empaquetado en arrays para optimizar gas,
 * las carreras, la currícula obligatoria, inscripciones y un puente de migración/recuperación de wallets.
 */
contract ConservatoryAcademy is AccessControl {
    bytes32 public constant REGISTRAR_ROLE = keccak256("REGISTRAR_ROLE");
    bytes32 public constant PROFESSOR_ROLE = keccak256("PROFESSOR_ROLE");
    bytes32 public constant MIGRATION_ADMIN_ROLE = keccak256("MIGRATION_ADMIN_ROLE");
    bytes32 public constant RECOVERER_ROLE = keccak256("RECOVERER_ROLE");

    struct SubjectRecord {
        uint8 score;         // 1 byte  -> Nota final del examen (0 a 100).
        uint8 attempts;      // 1 byte  -> Cantidad de veces que rindió la materia.
        uint32 approvalDate; // 4 bytes -> Timestamp unix de la aprobación.
        bool approved;       // 1 byte  -> Flag binario de estado académico.
        uint16 professorId;  // 2 bytes -> ID numérico del docente firmante.
    } // Ocupa exactamente 9 bytes (empaquetado secuencialmente en arrays de la EVM)

    // Variable de control del puente histórico
    bool public migrationPeriodActive;

    // Alumno (canonical) => Lista de registros académicos indexados por subjectId.
    // Al usar un array dinámico de una estructura de 9 bytes, la EVM empaqueta exactamente
    // 3 materias por cada slot de 32 bytes en memoria física de almacenamiento, lo que reduce
    // el gas de escritura en un 75% en escrituras sucesivas (SSTORE cálido de ~5000 gas en vez de ~20000 gas frío).
    mapping(address => SubjectRecord[]) public academicRecords;

    // Wallet => Dirección canonical del estudiante (para mantener consistencia tras migraciones de wallet)
    mapping(address => address) public canonicalStudent;

    // Dirección canonical del estudiante => Wallet actualmente activa
    mapping(address => address) public activeWalletOfCanonical;

    // Alumno canonical => ID Carrera
    mapping(address => uint256) public studentCareer;

    // ID Carrera => Lista de IDs de materias obligatorias
    mapping(uint256 => uint256[]) private careerCurriculum;

    // Wallet => Estado de regularidad activa
    mapping(address => bool) public activeStudents;

    event GradeSubmitted(address indexed student, uint256 indexed subjectId, uint8 score, uint16 indexed professorId);
    event CareerAssigned(address indexed student, uint256 indexed careerId);
    event CurriculumDefined(uint256 indexed careerId, uint256[] subjectIds);
    event HistoricalRecordImported(address indexed student, uint256 indexed subjectId);
    event MigrationDeactivated();
    event StudentWalletMigrated(address indexed compromisedWallet, address indexed newWallet, address indexed canonicalStudent);

    modifier onlyDuringMigration() {
        require(migrationPeriodActive, "El periodo de migracion historica ha finalizado");
        require(hasRole(MIGRATION_ADMIN_ROLE, msg.sender), "No autorizado para migraciones");
        _;
    }

    /**
     * @notice Inicializa el contrato y otorga todos los roles operativos al administrador inicial.
     * @param _initialAdmin Dirección que recibirá DEFAULT_ADMIN_ROLE, REGISTRAR_ROLE y RECOVERER_ROLE.
     */
    constructor(address _initialAdmin) {
        _grantRole(DEFAULT_ADMIN_ROLE, _initialAdmin);
        _grantRole(REGISTRAR_ROLE, _initialAdmin);
        _grantRole(RECOVERER_ROLE, _initialAdmin);
        migrationPeriodActive = true;
    }

    /**
     * @notice Define la currícula obligatoria para una carrera específica.
     * @param _careerId Identificador numérico de la carrera (debe ser > 0).
     * @param _subjectIds Array de IDs de materias que conforman el plan de estudio obligatorio.
     */
    function defineCurriculum(uint256 _careerId, uint256[] calldata _subjectIds) external onlyRole(REGISTRAR_ROLE) {
        require(_careerId > 0, "ID de carrera invalido");
        careerCurriculum[_careerId] = _subjectIds;
        emit CurriculumDefined(_careerId, _subjectIds);
    }

    /**
     * @notice Matricula a un estudiante en una carrera y activa su estatus.
     * @param _student Dirección de la wallet del alumno a matricular.
     * @param _careerId ID de la carrera en la que se inscribe el alumno.
     */
    function enrollStudent(address _student, uint256 _careerId) external onlyRole(REGISTRAR_ROLE) {
        require(_student != address(0), "Direccion de alumno invalida");
        require(_careerId > 0, "ID de carrera invalido");
        require(canonicalStudent[_student] == address(0), "El alumno ya esta registrado");

        canonicalStudent[_student] = _student;
        activeWalletOfCanonical[_student] = _student;
        studentCareer[_student] = _careerId;
        activeStudents[_student] = true;

        emit CareerAssigned(_student, _careerId);
    }

    /**
     * @notice Cambia el estado de actividad de un estudiante.
     * @param _student Dirección activa del alumno cuyo estado se desea modificar.
     * @param _status Nuevo estado de regularidad (true = activo, false = inactivo).
     */
    function setStudentActivity(address _student, bool _status) external onlyRole(REGISTRAR_ROLE) {
        address canonical = canonicalStudent[_student];
        require(canonical != address(0), "El alumno no esta registrado");
        require(activeWalletOfCanonical[canonical] == _student, "La wallet especificada no es la activa");
        activeStudents[_student] = _status;
    }

    /**
     * @notice Registra una nota académica ordinaria en el historial del alumno.
     * @param _student Dirección activa del alumno evaluado.
     * @param _subjectId ID de la materia rendida (índice en el array de registros académicos).
     * @param _score Nota obtenida (0–100). Se considera aprobada con 60 o más.
     * @param _professorId ID numérico del docente firmante del acta.
     */
    function submitGrade(
        address _student,
        uint256 _subjectId,
        uint8 _score,
        uint16 _professorId
    ) external onlyRole(PROFESSOR_ROLE) {
        require(activeStudents[_student], "El alumno no esta activo en la institucion");
        require(_score <= 100, "La nota debe estar entre 0 y 100");

        address canonical = canonicalStudent[_student];
        require(canonical != address(0), "El alumno no esta registrado");

        // Crecer el array dinámico hasta tener la capacidad del subjectId + 1
        uint256 currentLength = academicRecords[canonical].length;
        if (_subjectId >= currentLength) {
            uint256 growth = _subjectId + 1 - currentLength;
            for (uint256 i = 0; i < growth; i++) {
                academicRecords[canonical].push();
            }
        }

        SubjectRecord storage currentRecord = academicRecords[canonical][_subjectId];

        // Protección crítica: Una materia ya aprobada no puede ser sobrescrita.
        require(!currentRecord.approved, "La materia ya fue aprobada previamente");

        currentRecord.score = _score;
        currentRecord.attempts = currentRecord.attempts + 1;
        currentRecord.approvalDate = uint32(block.timestamp);
        currentRecord.approved = _score >= 60;
        currentRecord.professorId = _professorId;

        emit GradeSubmitted(_student, _subjectId, _score, _professorId);
    }

    /**
     * @notice Determina si el alumno ha aprobado de forma inmutable el 100% de su currícula asignada.
     * @param _student Dirección del alumno (puede ser wallet activa o wallet comprometida previa).
     * @return true si el alumno canonical ha aprobado todas las materias de su carrera; false en caso contrario.
     */
    function hasCompletedAllSubjects(address _student) external view returns (bool) {
        address canonical = canonicalStudent[_student];
        if (canonical == address(0)) return false;

        uint256 careerId = studentCareer[canonical];
        if (careerId == 0) return false;

        uint256[] memory requiredSubjects = careerCurriculum[careerId];
        if (requiredSubjects.length == 0) return false;

        for (uint256 i = 0; i < requiredSubjects.length; i++) {
            uint256 subjectId = requiredSubjects[i];
            if (subjectId >= academicRecords[canonical].length) {
                return false;
            }
            if (!academicRecords[canonical][subjectId].approved) {
                return false;
            }
        }
        return true;
    }

    /**
     * @notice MÓDULO DE MIGRACIÓN: carga en lote de datos históricos Web2 omitiendo firmas ordinarias.
     * @param _students Array de direcciones de alumnos a importar.
     * @param _subjectIds Array de IDs de materias correspondientes a cada registro.
     * @param _records Array de estructuras SubjectRecord con los datos académicos a importar.
     */
    function importHistoricalRecords(
        address[] calldata _students,
        uint256[] calldata _subjectIds,
        SubjectRecord[] calldata _records
    ) external onlyDuringMigration {
        require(_students.length == _subjectIds.length && _subjectIds.length == _records.length, "Longitud de arrays inconsistente");

        for (uint256 i = 0; i < _students.length; i++) {
            address student = _students[i];
            uint256 subjectId = _subjectIds[i];

            if (canonicalStudent[student] == address(0)) {
                canonicalStudent[student] = student;
                activeWalletOfCanonical[student] = student;
                activeStudents[student] = true;
            }

            address canonical = canonicalStudent[student];

            uint256 currentLength = academicRecords[canonical].length;
            if (subjectId >= currentLength) {
                uint256 growth = subjectId + 1 - currentLength;
                for (uint256 j = 0; j < growth; j++) {
                    academicRecords[canonical].push();
                }
            }

            academicRecords[canonical][subjectId] = _records[i];
            emit HistoricalRecordImported(student, subjectId);
        }
    }

    /**
     * @notice Clausura definitiva e irreversible del puente de migración histórica.
     */
    function deactivateMigration() external onlyRole(DEFAULT_ADMIN_ROLE) {
        migrationPeriodActive = false;
        emit MigrationDeactivated();
    }

    /**
     * @notice Permite migrar la identidad digital e historial de un alumno ante robo o pérdida de su wallet privada.
     * @param _compromisedWallet Dirección de la wallet comprometida que se dará de baja.
     * @param _newWallet Nueva dirección segura que asumirá la identidad del alumno.
     */
    function migrateStudentWallet(
        address _compromisedWallet,
        address _newWallet
    ) external onlyRole(RECOVERER_ROLE) {
        require(_compromisedWallet != address(0) && _newWallet != address(0), "Direcciones invalidas");
        address canonical = canonicalStudent[_compromisedWallet];
        require(canonical != address(0), "El alumno de origen no existe");
        require(activeWalletOfCanonical[canonical] == _compromisedWallet, "La billetera origen no es la billetera activa actual");
        require(canonicalStudent[_newWallet] == address(0), "La nueva billetera ya esta asociada a otro alumno");

        // Vincular la nueva wallet al alumno canonical
        canonicalStudent[_newWallet] = canonical;

        // Actualizar la billetera activa para este alumno
        activeWalletOfCanonical[canonical] = _newWallet;

        // Actualizar estados de actividad para que sólo la nueva wallet sea operativa
        activeStudents[_compromisedWallet] = false;
        activeStudents[_newWallet] = true;

        emit StudentWalletMigrated(_compromisedWallet, _newWallet, canonical);
    }
}

contracts/ConservatoryDiploma.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";

interface IAcademyCore {
    function hasCompletedAllSubjects(address _student) external view returns (bool);
    function migrateStudentWallet(address _compromisedWallet, address _newWallet) external;
}

/// @dev El token ya fue emitido y los SBT no pueden transferirse entre wallets.
error SBTTransferLocked();
/// @dev El graduado ya posee un diploma vigente.
error DiplomaAlreadyIssued(address graduate);
/// @dev El alumno no completó la totalidad de la currícula requerida.
error CurriculumIncomplete(address graduate);
/// @dev El token especificado no pertenece a la wallet indicada.
error TokenNotOwnedByWallet(uint256 tokenId, address claimedOwner);
/// @dev La nueva wallet ya cuenta con un diploma vigente.
error NewWalletAlreadyHasDiploma(address newWallet);

/**
 * @title ConservatoryDiploma
 * @author Valentino - UTN Blockchain TPI
 * @notice Emite diplomas de graduación como Soulbound Tokens (SBT) no transferibles,
 * implementando una validación atómica on-chain de materias y un módulo de reemisión administrativa por pérdida de llaves.
 */
contract ConservatoryDiploma is ERC721, AccessControl {
    bytes32 public constant ISSUER_ROLE = keccak256("ISSUER_ROLE");
    bytes32 public constant RECOVERER_ROLE = keccak256("RECOVERER_ROLE");

    IAcademyCore public academyContract;
    uint256 public nextTokenId;

    // Token ID => Hash Criptográfico del Legajo Completo
    mapping(uint256 => bytes32) public academicLegajos;

    // Alumno => Token ID del Diploma (Máximo 1 por alumno)
    mapping(address => uint256) public studentDiploma;

    event DiplomaIssued(address indexed graduate, uint256 indexed tokenId, bytes32 legajoHash);
    event DiplomaReissued(address indexed compromisedWallet, address indexed newWallet, uint256 indexed newTokenId);

    /**
     * @notice Inicializa el contrato con el administrador y la dirección de la Academia.
     * @param _academyContract Dirección del contrato ConservatoryAcademy desplegado.
     * @param _admin Dirección que recibirá los roles DEFAULT_ADMIN_ROLE, ISSUER_ROLE y RECOVERER_ROLE.
     */
    constructor(address _academyContract, address _admin) ERC721("Conservatory Soulbound Diploma", "CSBD") {
        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _grantRole(ISSUER_ROLE, _admin);
        _grantRole(RECOVERER_ROLE, _admin);
        academyContract = IAcademyCore(_academyContract);
    }

    /**
     * @notice Actualiza la dirección del contrato de Academia utilizado para validaciones.
     * @param _newAcademy Nueva dirección del contrato ConservatoryAcademy.
     */
    function setAcademyContract(address _newAcademy) external onlyRole(DEFAULT_ADMIN_ROLE) {
        academyContract = IAcademyCore(_newAcademy);
    }

    /**
     * @dev Bloqueo permanente de transferencias: transforma el NFT ordinario en un Soulbound Token.
     *      Se permite el mint (from == address(0)) y el burn (to == address(0)), pero no la transferencia.
     * @param to Dirección destino de la operación de transferencia interna.
     * @param tokenId ID del token involucrado.
     * @param auth Dirección autorizada a operar (según ERC-721 de OpenZeppelin v5).
     * @return Dirección anterior del propietario del token.
     */
    function _update(address to, uint256 tokenId, address auth) internal override returns (address) {
        address from = _ownerOf(tokenId);
        if (from != address(0) && to != address(0)) {
            revert SBTTransferLocked();
        }
        return super._update(to, tokenId, auth);
    }

    /**
     * @notice Emite el diploma SBT. Requiere validación atómica del plan académico on-chain.
     * @param _graduate Dirección del graduado que recibirá el diploma.
     * @param _legajoHash Hash criptográfico del legajo académico completo del graduado.
     */
    function mintDiploma(address _graduate, bytes32 _legajoHash) external onlyRole(ISSUER_ROLE) {
        if (studentDiploma[_graduate] != 0) revert DiplomaAlreadyIssued(_graduate);
        if (!academyContract.hasCompletedAllSubjects(_graduate)) revert CurriculumIncomplete(_graduate);

        nextTokenId++;
        uint256 tokenId = nextTokenId;

        _safeMint(_graduate, tokenId);
        academicLegajos[tokenId] = _legajoHash;
        studentDiploma[_graduate] = tokenId;

        emit DiplomaIssued(_graduate, tokenId, _legajoHash);
    }

    /**
     * @notice MECANISMO DE CONTINGENCIA: quema el token comprometido y genera uno nuevo con ID diferente
     *         para asegurar la consistencia temporal de indexadores off-chain, y migra el historial académico on-chain.
     * @param _compromisedWallet Dirección actual del diploma que será invalidado.
     * @param _newWallet Dirección segura que recibirá el diploma reemitido.
     * @param _tokenId ID del token a quemar, perteneciente a _compromisedWallet.
     */
    function burnAndReissue(
        address _compromisedWallet,
        address _newWallet,
        uint256 _tokenId
    ) external onlyRole(RECOVERER_ROLE) {
        if (ownerOf(_tokenId) != _compromisedWallet) revert TokenNotOwnedByWallet(_tokenId, _compromisedWallet);
        if (studentDiploma[_newWallet] != 0) revert NewWalletAlreadyHasDiploma(_newWallet);

        bytes32 legajo = academicLegajos[_tokenId];

        // 1. Quema el SBT original
        _burn(_tokenId);
        delete academicLegajos[_tokenId];
        delete studentDiploma[_compromisedWallet];

        // 2. Genera un nuevo token con ID incremental
        nextTokenId++;
        uint256 newTokenId = nextTokenId;

        _safeMint(_newWallet, newTokenId);
        academicLegajos[newTokenId] = legajo;
        studentDiploma[_newWallet] = newTokenId;

        // 3. Sincroniza la migración en el contrato núcleo de la Academia
        academyContract.migrateStudentWallet(_compromisedWallet, _newWallet);

        emit DiplomaReissued(_compromisedWallet, _newWallet, newTokenId);
    }

    /**
     * @notice Resuelve el conflicto de herencia múltiple entre ERC721 y AccessControl.
     * @param interfaceId Identificador de interfaz ERC-165 a verificar.
     * @return true si el contrato soporta la interfaz consultada.
     */
    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(ERC721, AccessControl)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }
}

